CREATE TABLE report_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,schedule_id uuid NOT NULL REFERENCES report_schedules(id) ON DELETE CASCADE,scheduled_for timestamptz NOT NULL,started_at timestamptz,finished_at timestamptz,status text NOT NULL DEFAULT 'queued' CHECK(status IN('queued','sending','sent','failed','retry_requested')),attempt integer NOT NULL DEFAULT 0,error_message text,provider_ids jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE warehouse_alert_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,alert_type text NOT NULL CHECK(alert_type IN('expiry','low_stock','overdue_order','accuracy')),severity text NOT NULL CHECK(severity IN('warning','critical')),message text NOT NULL,event_date date NOT NULL DEFAULT current_date,notified_at timestamptz,UNIQUE(company_id,alert_type,message,event_date));
ALTER TABLE report_runs ENABLE ROW LEVEL SECURITY;ALTER TABLE report_runs FORCE ROW LEVEL SECURITY;ALTER TABLE warehouse_alert_events ENABLE ROW LEVEL SECURITY;ALTER TABLE warehouse_alert_events FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_report_runs ON report_runs USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);
CREATE POLICY tenant_warehouse_alert_events ON warehouse_alert_events USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);
GRANT SELECT,INSERT,UPDATE,DELETE ON report_runs,warehouse_alert_events TO stockflow_app;
CREATE INDEX report_runs_schedule_status_idx ON report_runs(company_id,schedule_id,status,created_at DESC);
